CREATE TABLE x AS (
    SELECT timestamp_sequence('2024-01-01', 1_000_000) ts, 'a'::SYMBOL sym, x v FROM long_sequence(3)
) TIMESTAMP(ts) PARTITION BY DAY WAL DEDUP SKIP KEYS(ts, sym)

CREATE TABLE 'foo' ( 
	ts TIMESTAMP,
	s SYMBOL,
	i INT
) timestamp(ts) PARTITION BY DAY
DEDUP SKIP KEYS(ts,s);
